let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const t = String(o.type || "").toLowerCase();
const confidence = Number(o.confidence) || 0;
let type = t.startsWith("not") ? "not_food"
  : (t.includes("document") || t.includes("recipe")) ? "recipe_document"
  : t.includes("dish") ? "dish_photo" : "ingredients_photo";
// only reject an image when the model is sure it is not food
if (type === "not_food" && confidence < 0.6) type = "ingredients_photo";
return [{ json: { type, confidence, visible: String(o.visible || "").slice(0, 120) } }];

const tg = $('Telegram Trigger').first().json.message || {};
const caption = (tg.caption || "").toLowerCase();
const tm = caption.match(/(\d+)\s*(?:min|mins|minute|minutes|mn)\b/);
const max_minutes = tm ? Number(tm[1]) : null;
const vegetarian = /vegetarian|vegan|veggie|v[ée]g[ée]tarien|نباتي/.test(caption);
const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const seen = new Set(), ing = [], dropped = [];
for (const i of (Array.isArray(o.ingredients) ? o.ingredients : []).slice(0, 25)) {
  const name = clean(i && typeof i === "object" ? i.name : i);
  if (!name || seen.has(name)) continue;
  seen.add(name);
  const c = i && typeof i === "object" && i.confidence !== undefined ? Number(i.confidence) : 1;
  (c >= 0.6 ? ing : dropped).push(name);
}
const uncertain = [...new Set(dropped.concat(Array.isArray(o.uncertain) ? o.uncertain.map(clean) : []).filter(Boolean))];
return [{ json: {
  mode: "ingredients", source: "photo",
  query: ing.length ? "Ingredients: " + ing.join(", ") : "",
  title_query: "", user_ingredients: ing, uncertain, max_minutes, vegetarian
} }];

const tg = $('Telegram Trigger').first().json.message || {};
const caption = (tg.caption || "").toLowerCase();
const tm = caption.match(/(\d+)\s*(?:min|mins|minute|minutes|mn)\b/);
const max_minutes = tm ? Number(tm[1]) : null;
const vegetarian = /vegetarian|vegan|veggie|v[ée]g[ée]tarien|نباتي/.test(caption);
const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const GENERIC = new Set(["", "food", "meal", "dish", "plate", "bowl", "unknown", "unidentified"]);
let dish = clean(o.dish);
const conf = Number(o.confidence);
if (GENERIC.has(dish) || (conf >= 0 && conf < 0.25 && o.confidence !== undefined)) dish = "";
const main = [...new Set((Array.isArray(o.main_ingredients) ? o.main_ingredients : []).map(clean).filter(Boolean))].slice(0, 6);
const alternatives = (Array.isArray(o.alternatives) ? o.alternatives : []).map(clean).filter(x => x && !GENERIC.has(x) && x !== dish).slice(0, 2);
return [{ json: {
  mode: "dish", source: "photo",
  query: dish ? dish + (main.length ? ". Main ingredients: " + main.join(", ") : "") : "",
  title_query: dish, alternatives, user_ingredients: [], uncertain: [], max_minutes, vegetarian
} }];

const tg = $('Telegram Trigger').first().json.message || {};
const caption = (tg.caption || "").toLowerCase();
const tm = caption.match(/(\d+)\s*(?:min|mins|minute|minutes|mn)\b/);
const max_minutes = tm ? Number(tm[1]) : null;
const vegetarian = /vegetarian|vegan|veggie|v[ée]g[ée]tarien|نباتي/.test(caption);
const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const line = x => typeof x === "string" ? x.trim()
  : [x && x.quantity, x && (x.item || x.name)].filter(Boolean).join(" ").trim();
const ingredients = (Array.isArray(o.ingredients) ? o.ingredients : []).map(line).filter(Boolean);
const steps = (Array.isArray(o.steps) ? o.steps : []).map(s => String(s).trim()).filter(Boolean);
const names = [...new Set((Array.isArray(o.ingredient_names) ? o.ingredient_names : []).map(clean).filter(Boolean))].slice(0, 25);
const title = String(o.title || "").trim();
const titleEn = String(o.title_en || o.title || "").trim();
const ok = ingredients.length > 0 || steps.length > 0;
const time = o.time != null ? o.time : (o.time_minutes != null ? o.time_minutes : null);
let query = "";
if (ok) {
  query = "Recipe: " + (titleEn || steps.slice(0, 2).join(" ").slice(0, 120) || "recipe")
    + (names.length ? ". Ingredients: " + names.slice(0, 10).join(", ") : "");
}
return [{ json: {
  mode: "document", source: "photo", query,
  title_query: clean(titleEn), user_ingredients: names, uncertain: [], max_minutes, vegetarian,
  parsed: { title, servings: o.servings != null ? o.servings : null, time, ingredients, steps, complete: o.complete !== false }
} }];

const raw = ((($('Telegram Trigger').first().json.message || {}).text) || "").trim();
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

// Handle /start, empty, or help intent
if (!raw || raw.startsWith("/") || o.intent === "help") {
  return [{ json: { mode: "help", source: "text", query: "", user_ingredients: [], uncertain: [] } }];
}

const items = [...new Set((Array.isArray(o.items) ? o.items : [])
  .map(x => String(x).toLowerCase().trim()).filter(Boolean))];
const maxMin = Number(o.max_minutes) > 0 ? Number(o.max_minutes) : null;
const veg = o.vegetarian === true;

if (o.intent === "ingredients" && items.length) {
  return [{ json: { mode: "ingredients", source: "text", query: "Ingredients: " + items.join(", "), title_query: "",
    user_ingredients: items, uncertain: [], max_minutes: maxMin, vegetarian: veg } }];
}

const dish = ((o.dish && String(o.dish).trim()) || raw).toLowerCase();
return [{ json: { mode: "text", source: "text", query: dish, title_query: dish, user_ingredients: [], uncertain: [],
  max_minutes: maxMin, vegetarian: veg } }];

const n = $('Has query').first().json;
const hits = ($json.result || []).filter(h => h.payload && Array.isArray(h.payload.ingredients));
const doc = n.mode === "document";

const STAPLES = ["salt", "pepper", "black pepper", "white pepper", "water", "hot water", "warm water",
  "cold water", "boiling water", "oil", "vegetable oil", "olive oil", "cooking oil", "cooking spray",
  "sugar", "ice", "ice cubes", "kosher salt", "sea salt", "salt and pepper"];
const stem = w => {
  if (w.length <= 3) return w;
  if (w.endsWith("ies")) return w.slice(0, -3) + "y";
  if (w.endsWith("oes")) return w.slice(0, -2);
  if (w.endsWith("ss")) return w;
  if (w.endsWith("s")) return w.slice(0, -1);
  return w;
};
const toks = s => String(s).toLowerCase().replace(/[^a-z\s]/g, " ").split(/\s+/).filter(Boolean).map(stem);
const STAPLE_KEYS = new Set(STAPLES.map(s => toks(s).join(" ")));
const isStaple = r => STAPLE_KEYS.has(toks(r).join(" "));

const user = (n.user_ingredients || []).map(u => toks(u)).filter(t => t.length);
const matches = (r, u) => {
  const R = toks(r);
  return u.every(t => R.includes(t)) || R.every(t => u.includes(t));
};
const analyse = h => {
  const pantry = [], needed = [];
  h.payload.ingredients.forEach(r => (isStaple(r) ? pantry : needed).push(r));
  const have = needed.filter(r => user.some(u => matches(r, u)));
  const missing = needed.filter(r => !user.some(u => matches(r, u)));
  const usedUser = user.filter(u => needed.some(r => matches(r, u))).length;
  return { h, pantry, needed, have, missing, usedUser, nameScore: 0, overlap: 0 };
};
const pack = a => ({
  name: a.h.payload.name, minutes: a.h.payload.minutes, steps: a.h.payload.steps || [],
  pantry: a.pantry, needed: a.needed, have: a.have, missing: a.missing, score: a.h.score
});

const qt = [...new Set(toks(n.title_query || "").filter(t => t.length > 2))];
const nameScore = a => qt.length ? qt.filter(t => toks(a.h.payload.name).includes(t)).length / qt.length : 0;

let ranked = [];
if (n.mode === "ingredients" && user.length) {
  const all = hits.map(analyse);
  const minUsed = Math.min(2, user.length);
  let pool = all.filter(a => a.usedUser >= minUsed && a.needed.length >= 3);
  if (!pool.length) pool = all.filter(a => a.usedUser >= 1);
  if (!pool.length) pool = all;
  ranked = pool.sort((a, b) => (a.missing.length - b.missing.length)
    || (b.usedUser - a.usedUser) || ((b.h.score || 0) - (a.h.score || 0)));
} else {
  ranked = hits.map(analyse);
  ranked.forEach(a => {
    a.nameScore = nameScore(a);
    a.overlap = doc && a.needed.length ? a.have.length / a.needed.length : 0;
  });
  const s = a => a.nameScore * (doc ? 2 : 1) + a.overlap;
  ranked.sort((a, b) => (s(b) - s(a)) || ((b.h.score || 0) - (a.h.score || 0)));
  // outside document mode there is no user pantry to compare with
  if (!doc) ranked.forEach(a => { a.have = []; a.missing = []; });
}

const best = ranked[0];
let match = "n/a";
if (best && n.mode !== "ingredients") {
  match = (best.nameScore >= 0.67 || (doc && best.overlap >= 0.6)) ? "good"
    : (best.nameScore > 0 || (doc && best.overlap >= 0.3)) ? "partial" : "weak";
}
const chosen = best ? pack(best) : null;
const alternatives = ranked.slice(1, 3).map(a => ({ name: a.h.payload.name, missing: a.missing.length, minutes: a.h.payload.minutes }));

// ---- context handed to the Chef (and reused by the Validator)
const p = n.parsed || null;
const L = [];
L.push("MODE: " + n.mode);
if (doc && p) {
  L.push("User's own recipe title: " + (p.title || "unknown"));
  L.push("User's recipe ingredients: " + p.ingredients.slice(0, 20).join("; "));
  L.push("User's recipe steps: " + p.steps.slice(0, 6).map(x => String(x).slice(0, 140)).join(" | ").slice(0, 700));
  L.push(chosen ? "Similar knowledge-base recipe (reference only): " + chosen.name + (chosen.minutes ? " (" + chosen.minutes + " min)" : "") : "Similar knowledge-base recipe: none");
} else if (chosen) {
  L.push("Recipe: " + chosen.name + (chosen.minutes ? " (" + chosen.minutes + " min)" : ""));
  L.push("Recipe ingredients: " + chosen.needed.concat(chosen.pantry).slice(0, 25).join(", "));
  L.push("Recipe steps (first ones): " + chosen.steps.slice(0, 6).map(x => String(x).slice(0, 140)).join(" | ").slice(0, 700));
}
const ing = n.mode === "ingredients";
L.push("User has: " + (ing && (n.user_ingredients || []).length ? n.user_ingredients.join(", ") : "NONE"));
L.push("Missing: " + (ing && chosen && chosen.missing.length ? chosen.missing.join(", ") : "NONE"));
L.push("Vegetarian requested: " + (n.vegetarian ? "yes" : "no"));

return [{ json: {
  mode: n.mode, source: n.source || "", query: n.query, title_query: n.title_query || "",
  user_ingredients: n.user_ingredients || [], uncertain: n.uncertain || [],
  vegetarian: !!n.vegetarian, max_minutes: n.max_minutes || null,
  parsed: p, detected_alternatives: n.alternatives || [],
  chosen, alternatives, retrieved: hits.length, match,
  chef_context: L.join("\n")
} }];

const r = $('Rank recipes').first().json;
const chef = $('Parse chef').first().json.chef;
let v = null;
try { v = JSON.parse($json.message.content); } catch (e) {}

const c = r.chosen;
const doc = r.mode === "document";
if (!c && !doc) return [{ json: { answer: "I could not find a matching recipe in the knowledge base. Try other ingredients or a different dish name.", mode: r.mode } }];

// ---- validator verdicts (fail closed for substitutions, open for intro/tip)
const VEG_BAD = /\b(chicken|beef|pork|lamb|veal|bacon|ham|sausage|salami|prosciutto|fish|tuna|salmon|anchov\w*|shrimp|prawn\w*|gelatin\w*|lard|meat\w*|turkey|duck|broth|stock)\b/i;
let subs = chef.substitutions || [];
const sv = v && (Array.isArray(v.substitutions) ? v.substitutions : v.verdicts);
if (Array.isArray(sv) && sv.length === subs.length) subs = subs.filter((s, i) => sv[i] !== false);
else if (subs.length) subs = [];
if (r.vegetarian) subs = subs.filter(s => !VEG_BAD.test(s.replace_with));
const intro = v && v.intro_ok === false ? "" : chef.intro;
const tip = v && v.tip_ok === false ? "" : chef.tip;

const cap = s => { s = String(s).trim(); return s.charAt(0).toUpperCase() + s.slice(1); };
const mins = x => x ? " (" + x + " min)" : "";
const head = [], foot = [];
let steps = [], stepsLabel = "Steps:";

if (doc) {
  const p = r.parsed || { ingredients: [], steps: [] };
  head.push(cap(p.title || "Recipe from your document"));
  const meta = [];
  if (p.servings) meta.push("Servings: " + p.servings);
  if (p.time) meta.push("Time: " + p.time + (/^\d+$/.test(String(p.time)) ? " min" : ""));
  if (meta.length) head.push(meta.join(" | "));
  if (intro) head.push(intro);
  if (p.complete === false) head.push("(Parts of the image were hard to read, please double-check the details.)");
  head.push("");
  head.push("Ingredients:");
  (p.ingredients.length ? p.ingredients : ["(none detected)"]).forEach(i => head.push("- " + i));
  head.push("");
  if (p.steps.length) {
    steps = p.steps.slice(0, 20).map((s, i) => (i + 1) + ". " + cap(s));
  } else if (c) {
    stepsLabel = "Steps (none readable in your image, suggested from " + cap(c.name) + "):";
    steps = (c.steps || []).slice(0, 12).map((s, i) => (i + 1) + ". " + cap(s));
  } else {
    steps = ["(none detected)"];
  }
  if (c) {
    const label = r.match === "good" ? "close match" : r.match === "partial" ? "partial match" : "loose match";
    foot.push("");
    foot.push("Knowledge base (" + label + "): " + cap(c.name) + mins(c.minutes));
    if (r.match !== "weak") {
      if (c.have.length) foot.push("Shared ingredients: " + c.have.slice(0, 8).join(", "));
      if (c.missing.length) foot.push("Also used there: " + c.missing.slice(0, 6).join(", "));
    }
  } else {
    foot.push("");
    foot.push("No similar recipe was found in the knowledge base.");
  }
  if (tip) { foot.push(""); foot.push("Tip: " + tip); }
} else {
  head.push(cap(c.name) + mins(c.minutes));
  if (r.mode === "dish" && r.source === "photo" && r.title_query) {
    const alt = (r.detected_alternatives || []);
    head.push("Detected dish: " + r.title_query + (alt.length ? " (could also be: " + alt.join(", ") + ")" : ""));
  }
  if (r.mode !== "ingredients" && r.match === "weak") head.push("No exact recipe found, this is the closest one in the knowledge base.");
  if (intro) head.push(intro);
  head.push("");
  if (r.mode === "ingredients") {
    head.push((r.source === "photo" ? "Detected in your photo: " : "Your ingredients: ") + r.user_ingredients.join(", "));
    if (r.uncertain.length) head.push("Not sure about (ignored): " + [...new Set(r.uncertain)].join(", "));
    head.push("");
    head.push("You have (" + c.have.length + " of " + c.needed.length + "): " + (c.have.join(", ") || "-"));
    head.push(c.missing.length ? "Missing (" + c.missing.length + "): " + c.missing.join(", ") : "You have everything you need!");
    if (c.pantry.length) head.push("Pantry basics: " + c.pantry.join(", "));
    if (subs.length) { head.push(""); head.push("Substitutions:"); subs.forEach(s => head.push("- " + s.missing + " -> " + s.replace_with)); }
  } else {
    head.push("Ingredients needed: " + c.needed.concat(c.pantry).join(", "));
  }
  head.push("");
  steps = (c.steps || []).slice(0, 12).map((s, i) => (i + 1) + ". " + cap(s));
  if (r.alternatives.length) {
    foot.push("");
    foot.push(r.mode === "ingredients"
      ? "Other close options: " + r.alternatives.map(a => cap(a.name) + " (missing " + a.missing + ")").join("; ")
      : "Other matches: " + r.alternatives.map(a => cap(a.name)).join("; "));
  }
  if (tip) { foot.push(""); foot.push("Tip: " + tip); }
}

const build = () => head.concat([stepsLabel], steps, foot).join("\n");
let out = build();
while (out.length > 3900 && steps.length > 3) { steps.pop(); out = build(); }
out = out.replace(/[*_`\[\]]/g, "");
if (out.length > 4000) out = out.slice(0, 3990) + "...";
return [{ json: { answer: out, mode: r.mode, chosen: c ? c.name : null, match: r.match, rule_substitutions_kept: subs.length } }];

