const r = $('Rank recipes').first().json;
const c = r.chosen || { missing: [] };
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const strip = s => String(s || "").replace(/[*_`#\[\]]/g, "").replace(/\s+/g, " ").trim();
const norm = s => strip(s).toLowerCase();
const clip = (s, max) => {
  s = strip(s);
  if (s.length <= max) return s;
  const first = s.match(/^.*?[.!?](\s|$)/);
  if (first && first[0].trim().length <= max) return first[0].trim();
  return s.slice(0, max).replace(/\s+\S*$/, "") + "...";
};
// substitutions only make sense when the user's pantry was compared to the recipe
const missingSet = r.mode === "ingredients" ? (c.missing || []).map(norm) : [];
const seen = new Set();
const subs = (Array.isArray(o.substitutions) ? o.substitutions : [])
  .filter(s => s && s.missing && s.replace_with
    && missingSet.includes(norm(s.missing))
    && norm(s.replace_with) !== norm(s.missing)
    && !missingSet.includes(norm(s.replace_with))
    && !seen.has(norm(s.missing)) && seen.add(norm(s.missing)))
  .slice(0, 3)
  .map(s => ({ missing: strip(s.missing), replace_with: strip(s.replace_with) }));
const chef = { intro: clip(o.intro, 220), tip: clip(o.tip, 200), substitutions: subs };
const validator_input = (r.chef_context || "") + "\n\nOutput to check:\n" + JSON.stringify(chef);
return [{ json: { chef, validator_input } }];
